b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
var photos=[], currentSheet=0, totalSheets=0;
var stage=document.getElementById('stage');
var dynamicArea=document.getElementById('dynamic-area');
var endSheet=document.getElementById('sheet-end');
var isPortrait=window.matchMedia("(max-width: 850px) and (orientation: portrait)").matches;

function loadFeed(json){
    if(!json.feed||!json.feed.entry){useDemo();return;}
    var entries=json.feed.entry;
    for(var i=0;i<entries.length;i++){
        var div=document.createElement('div');
        div.innerHTML=entries[i].content.$t;
        var imgs=div.getElementsByTagName('img');
        for(var k=0;k<imgs.length;k++){
            var src=imgs[k].src;
            if(src.indexOf('blogspot')>-1||src.indexOf('googleusercontent')>-1){
                src=src.replace(/\/s\d+(-c)?\//,'/s2048/').replace(/=s\d+/,'=s2048');
            }
            photos.push(src);
        }
    }
    if(photos.length>0)buildBook();else useDemo();
}

function useDemo(){
    var c=[['FFD3E0','cc5080'],['D3F0FF','4080cc'],['D3FFD3','408040'],['FFF3D3','c08030'],['EFD3FF','8040cc'],['FFE5D3','c06030']];
    for(var i=0;i<12;i++) photos.push("https://via.placeholder.com/1000x1000/"+c[i%6][0]+"/"+c[i%6][1]+"?text=Memory+"+(i+1));
    buildBook();
}

(function(){
    dynamicArea.innerHTML='<div class="loader">Memuat kenangan...</div>';
    var s=document.createElement('script');
    s.src="/feeds/posts/default?alt=json-in-script&callback=loadFeed&max-results=50";
    s.onerror=function(){useDemo();};
    document.body.appendChild(s);
})();

var PAGE_PATTERN=[2,4,1,4,2,6,3];

function buildBook(){
    dynamicArea.innerHTML='';
    var photoIdx=0, sheetCount=0, pageNum=0, patIdx=0;

    // For portrait/mobile: insert welcome page as first sheet
    if(isPortrait){
        sheetCount++;
        var welcomeSheet=document.createElement('div');
        welcomeSheet.className='sheet'; welcomeSheet.id='sheet-'+sheetCount; welcomeSheet.style.zIndex=100-sheetCount;
        welcomeSheet.innerHTML=
            '<div class="face front"><div style="display:flex;height:100%;align-items:center;justify-content:center;flex-direction:column;padding:36px;text-align:center;background:linear-gradient(160deg,#fff9fb,#fff0f5);gap:12px;">'
            +'<div style="font-size:3rem;line-height:1;">🎠</div>'
            +'<h2 style="font-family:\'Baloo 2\',sans-serif;color:#e8508a;font-size:1.7rem;margin:0;letter-spacing:1px;">Welcome!</h2>'
            +'<div class="rainbow-bar" style="width:80px;"></div>'
            +'<p style="font-family:\'Nunito\',sans-serif;font-size:0.95rem;line-height:1.8;color:#999;margin:0;">"A happy childhood<br/>is the most beautiful memory. 🌈"</p>'
            +'<div style="font-size:1.8rem;margin-top:6px;">🎈 💗 🎀</div>'
            +'</div></div>'
            +'<div class="face back"><div style="display:flex;height:100%;align-items:center;justify-content:center;font-size:2.5rem;">&#128151;</div></div>';
        dynamicArea.appendChild(welcomeSheet);
    }

    while(photoIdx<photos.length){
        sheetCount++;
        pageNum++;
        var sheet=document.createElement('div');
        sheet.className='sheet'; sheet.id='sheet-'+sheetCount; sheet.style.zIndex=100-sheetCount;
        var cF=PAGE_PATTERN[patIdx%PAGE_PATTERN.length]; patIdx++;
        var frontHTML=generateGrid(photoIdx,cF,false,pageNum);
        photoIdx+=Math.min(cF,photos.length-photoIdx);
        var backHTML='';
        if(isPortrait){
            backHTML='<div class="face back"><div style="display:flex;height:100%;align-items:center;justify-content:center;font-size:2.5rem;">&#128151;</div></div>';
        } else {
            if(photoIdx<photos.length){
                pageNum++;
                var cB=PAGE_PATTERN[patIdx%PAGE_PATTERN.length]; patIdx++;
                backHTML=generateGrid(photoIdx,cB,true,pageNum);
                photoIdx+=Math.min(cB,photos.length-photoIdx);
            } else backHTML='<div class="face back"></div>';
        }
        sheet.innerHTML=frontHTML+backHTML;
        dynamicArea.appendChild(sheet);
    }
    totalSheets=sheetCount+1;
    endSheet.id='sheet-'+totalSheets; endSheet.style.zIndex=1;
    optimizeVisibility();
}

function generateGrid(startIndex,count,isBack,pageNum){
    if(startIndex+count>photos.length) count=photos.length-startIndex;
    if(count===0) return '<div class="face '+(isBack?'back':'front')+'"></div>';
    if(count<1) count=1;
    var html='<div class="face '+(isBack?'back':'front')+'"><div class="grid-layout layout-'+count+'">';
    for(var i=0;i<count;i++){
        var idx=startIndex+i;
        if(idx<photos.length) html+='<div class="photo-item" onclick="openLightbox('+idx+')"><img src="'+photos[idx]+'" loading="lazy"></div>';
    }
    html+='</div><div class="pg-num">'+pageNum+'</div></div>';
    return html;
}

function optimizeVisibility(){
    for(var i=0;i<=totalSheets;i++){
        var el=document.getElementById('sheet-'+i); if(!el) continue;
        if(i===0){el.classList.toggle('inactive',currentSheet>3);continue;}
        el.classList.toggle('inactive',i<currentSheet-3||i>currentSheet+3);
    }
}

function openBook(){stage.classList.remove('closed');stage.classList.add('opened');nextPage();}
function closeBook(){
    for(var i=totalSheets;i>=1;i--){var el=document.getElementById('sheet-'+i);if(el){el.classList.remove('flipped');el.style.zIndex=100-i;}}
    var cover=document.getElementById('sheet-0'); cover.classList.remove('flipped'); cover.style.zIndex=1000;
    currentSheet=0; stage.classList.remove('opened'); stage.classList.add('closed'); optimizeVisibility();
}
function nextPage(){
    if(currentSheet<totalSheets){
        var el=document.getElementById('sheet-'+currentSheet);
        if(el){el.style.zIndex=1000;el.classList.add('flipped');setTimeout(function(){el.style.zIndex=200+currentSheet;},400);currentSheet++;optimizeVisibility();}
    }
}
function prevPage(){
    if(currentSheet>0){
        currentSheet--;
        var el=document.getElementById('sheet-'+currentSheet);
        if(el){el.style.zIndex=1000;el.classList.remove('flipped');setTimeout(function(){if(currentSheet===0){el.style.zIndex=1000;closeBook();}else{el.style.zIndex=100-currentSheet;}},400);optimizeVisibility();}
    }
}

var startX=0,endX=0,isLbOpen=false,isDragging=false;
document.addEventListener('mousedown',function(e){if(!isLbOpen){startX=e.clientX;isDragging=true;}});
document.addEventListener('mouseup',function(e){if(isLbOpen||!isDragging)return;isDragging=false;endX=e.clientX;processInput(e.target);});
document.addEventListener('touchstart',function(e){if(isLbOpen){lbTouchStart(e);return;}startX=e.changedTouches[0].clientX;});
document.addEventListener('touchend',function(e){if(isLbOpen){lbTouchEnd(e);return;}endX=e.changedTouches[0].clientX;processInput(e.target);});
function processInput(t){
    if(Math.abs(endX-startX)>50){if(endX<startX){if(currentSheet===0)openBook();else nextPage();}else{prevPage();}return;}
    if(t.tagName==='IMG'||t.classList.contains('photo-item'))return;
    if(endX>window.innerWidth/2){if(currentSheet===0)openBook();else nextPage();}else{prevPage();}
}

var lb=document.getElementById('lightbox'),lbImg=document.getElementById('lb-img'),
    lbCounter=document.getElementById('lb-counter'),lbContainer=document.getElementById('lb-container'),
    scale=1,currentPhotoIndex=0,pointX=0,pointY=0,pStartX=0,pStartY=0,isPanning=false,lbTxS=0,lbTxE=0;

function openLightbox(idx){isLbOpen=true;currentPhotoIndex=idx;lbImg.src=photos[idx];lb.classList.add('active');updateCounter();resetZoom();if(window.event)window.event.stopPropagation();}
function updateCounter(){lbCounter.innerText=(currentPhotoIndex+1)+' / '+photos.length;}
function closeLightbox(){isLbOpen=false;lb.classList.remove('active');}
lb.addEventListener('click',function(e){if(e.target===lb||e.target===lbContainer)closeLightbox();});
function toggleZoom(){if(scale===1)maxZoom();else resetZoom();}
function maxZoom(){scale=2.5;lbImg.classList.add('zoomed');updateTransform();}
function resetZoom(){scale=1;pointX=0;pointY=0;lbImg.classList.remove('zoomed');updateTransform();}
function updateTransform(){lbImg.style.transform='translate('+pointX+'px,'+pointY+'px) scale('+scale+')';}
lbImg.addEventListener('mousedown',function(e){if(scale<=1)return;e.preventDefault();isPanning=true;pStartX=e.clientX-pointX;pStartY=e.clientY-pointY;lbImg.style.transition='none';});
window.addEventListener('mousemove',function(e){if(!isPanning)return;e.preventDefault();pointX=e.clientX-pStartX;pointY=e.clientY-pStartY;updateTransform();});
window.addEventListener('mouseup',function(){if(isPanning){isPanning=false;lbImg.style.transition='transform 0.3s ease';}});
function lbTouchStart(e){if(scale>1){isPanning=true;pStartX=e.touches[0].clientX-pointX;pStartY=e.touches[0].clientY-pointY;lbImg.style.transition='none';}else{lbTxS=e.changedTouches[0].clientX;}}
lbImg.addEventListener('touchmove',function(e){if(scale>1&&isPanning){e.preventDefault();pointX=e.touches[0].clientX-pStartX;pointY=e.touches[0].clientY-pStartY;updateTransform();}});
function lbTouchEnd(e){if(scale>1){isPanning=false;lbImg.style.transition='transform 0.3s ease';}else{lbTxE=e.changedTouches[0].clientX;if(Math.abs(lbTxE-lbTxS)>50){if(lbTxE<lbTxS)nextPhoto();else prevPhoto();}}}
function changePhoto(newIdx,dir){lbImg.style.transition='all 0.3s ease';lbImg.style.opacity=0;lbImg.style.transform=dir==='next'?'translateX(-30px)':'translateX(30px)';setTimeout(function(){currentPhotoIndex=newIdx;lbImg.src=photos[newIdx];updateCounter();resetZoom();lbImg.style.transition='none';lbImg.style.transform=dir==='next'?'translateX(30px)':'translateX(-30px)';void lbImg.offsetWidth;lbImg.style.transition='all 0.3s ease';lbImg.style.opacity=1;lbImg.style.transform='translate(0,0) scale(1)';},300);}
function nextPhoto(){if(currentPhotoIndex<photos.length-1)changePhoto(currentPhotoIndex+1,'next');}
function prevPhoto(){if(currentPhotoIndex>0)changePhoto(currentPhotoIndex-1,'prev');}
document.addEventListener('keydown',function(e){if(isLbOpen){if(e.key==='Escape')closeLightbox();if(e.key==='ArrowRight')nextPhoto();if(e.key==='ArrowLeft')prevPhoto();return;}if(e.key==='ArrowRight')nextPage();if(e.key==='ArrowLeft')prevPage();});
//
